/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `trg_people_after_update` AFTER UPDATE ON `tb_people` FOR EACH ROW BEGIN
    INSERT INTO `tb_logs` (`table_name`, `table_operation`, `db_user`, `operation_date`, `description`, `operation_status`)
    VALUES ('tb_people', 'Update', USER(), CURRENT_TIMESTAMP,
            CONCAT('Registro actualizado. ID=', NEW.person_ID, ', user_ID=', IFNULL(NEW.user_ID, 'NULL')),
            b'1');
END */;;
