CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_attend_order`(IN p_order_id INT UNSIGNED)
BEGIN
  DECLARE v_status VARCHAR(30);
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
  START TRANSACTION;
  SELECT status_string INTO v_status FROM tb_buyer_orders WHERE ID = p_order_id FOR UPDATE;
  IF v_status IS NULL OR v_status <> 'Payed' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'La orden no está pagada';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM tb_seller_orders WHERE order_ID = p_order_id) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'La orden no tiene pedidos de vendedor';
  END IF;
  IF EXISTS (
    SELECT 1 FROM tbd_users_offer_products o
    JOIN (
      SELECT oi.product_offer_ID, SUM(oi.quantity) AS requested_stock
      FROM tbd_order_items oi
      JOIN tb_seller_orders so ON so.ID = oi.seller_order_ID
      WHERE so.order_ID = p_order_id
      GROUP BY oi.product_offer_ID
    ) requested ON requested.product_offer_ID = o.product_offer_ID
    WHERE o.available_stock < requested.requested_stock
  ) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Inventario insuficiente para atender la orden';
  END IF;
  UPDATE tbd_users_offer_products o
  JOIN (
    SELECT oi.product_offer_ID, SUM(oi.quantity) AS requested_stock
    FROM tbd_order_items oi
    JOIN tb_seller_orders so ON so.ID = oi.seller_order_ID
    WHERE so.order_ID = p_order_id
    GROUP BY oi.product_offer_ID
  ) requested ON requested.product_offer_ID = o.product_offer_ID
  SET o.available_stock = o.available_stock - requested.requested_stock;
  UPDATE tb_seller_orders SET fulfillment_status = 'Preparing' WHERE order_ID = p_order_id;
  UPDATE tb_buyer_orders SET status_string = 'Attended' WHERE ID = p_order_id;
  COMMIT;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
