CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_authorize_payment`(IN p_payment_id INT UNSIGNED)
BEGIN
  DECLARE v_order_id INT UNSIGNED;
  DECLARE v_amount DECIMAL(12,2);
  DECLARE v_status VARCHAR(30);
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
  START TRANSACTION;
  SELECT order_ID, amount, payment_status INTO v_order_id, v_amount, v_status
  FROM tb_payments WHERE ID = p_payment_id FOR UPDATE;
  IF v_status IS NULL THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Pago inexistente';
  END IF;
  IF v_status <> 'Pending' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'El pago no está pendiente';
  END IF;
  INSERT INTO tb_payment_transactions (payment_ID, event_type, amount, event_reference, remarks)
  VALUES (p_payment_id, 'Authorized', v_amount, CONCAT('AUTH-', UUID()), 'Autorización de pago');
  INSERT INTO tb_payment_transactions (payment_ID, event_type, amount, event_reference, remarks)
  VALUES (p_payment_id, 'Captured', v_amount, CONCAT('CAP-', UUID()), 'Captura de pago');
  UPDATE tb_payments SET payment_status = 'Paid', paid_date = NOW() WHERE ID = p_payment_id;
  UPDATE tb_buyer_orders SET status_string = 'Payed' WHERE ID = v_order_id;
  COMMIT;
END ;;
DELIMITER ;
