CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_deliver_order`(IN p_order_id INT UNSIGNED)
BEGIN
  DECLARE v_status VARCHAR(30);
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
  START TRANSACTION;
  SELECT status_string INTO v_status FROM tb_buyer_orders WHERE ID = p_order_id FOR UPDATE;
  IF v_status IS NULL OR v_status <> 'Attended' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'La orden no ha sido atendida';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM tb_seller_orders WHERE order_ID = p_order_id) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'La orden no tiene pedidos de vendedor';
  END IF;
  INSERT INTO tb_shipments (seller_order_ID, carrier, tracking_number, shipment_status, shipped_date, estimated_delivery_date, delivered_date)
  SELECT so.ID, 'Estafeta', CONCAT('TRK', LPAD(so.ID, 8, '0')), 'Delivered', NOW(), NOW(), NOW()
  FROM tb_seller_orders so
  WHERE so.order_ID = p_order_id
    AND NOT EXISTS (SELECT 1 FROM tb_shipments s WHERE s.seller_order_ID = so.ID);
  UPDATE tb_shipments s JOIN tb_seller_orders so ON so.ID = s.seller_order_ID
  SET s.shipment_status = 'Delivered', s.delivered_date = NOW()
  WHERE so.order_ID = p_order_id;
  UPDATE tb_seller_orders SET fulfillment_status = 'Delivered' WHERE order_ID = p_order_id;
  UPDATE tb_buyer_orders SET status_string = 'Delivered' WHERE ID = p_order_id;
  COMMIT;
END ;;
DELIMITER ;
