/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_insert_single_user`(
    IN  p_nickname  VARCHAR(50),
    IN  p_country   VARCHAR(50),
    IN  p_birthdate DATE,
    IN  p_is_active TINYINT(1),
    OUT p_inserted_id INT
)
BEGIN
    DECLARE v_email   VARCHAR(80);
    DECLARE v_nick    VARCHAR(100);
    DECLARE v_country CHAR(2);

    SET v_email = fn_generate_random_email(p_nickname);
    -- 6 dígitos (en res eran 3) para evitar choques con el UNIQUE de nick
    SET v_nick  = CONCAT(p_nickname, '_', FLOOR(100000 + RAND() * 900000));

    -- tb_people.country_code es CHAR(2): se convierte el nombre a código ISO
    SET v_country = CASE UPPER(TRIM(IFNULL(p_country, '')))
        WHEN 'MEXICO' THEN 'MX' WHEN 'MÉXICO' THEN 'MX'
        WHEN 'USA' THEN 'US' WHEN 'UNITED STATES' THEN 'US' WHEN 'ESTADOS UNIDOS' THEN 'US'
        WHEN 'CANADA' THEN 'CA' WHEN 'CANADÁ' THEN 'CA'
        ELSE IF(CHAR_LENGTH(TRIM(IFNULL(p_country, ''))) = 2, UPPER(TRIM(p_country)), NULL)
    END;

    INSERT INTO `tb_users` (`email`, `nick`, `password`, `status`, `creation_date`)
    VALUES (v_email, v_nick, SHA2(CONCAT(v_email, RAND()), 256), IF(p_is_active = 1, b'1', b'0'), NOW());

    SET p_inserted_id = LAST_INSERT_ID();

    INSERT INTO `tb_people` (`user_ID`, `given_names`, `birth_date`, `country_code`, `status`)
    VALUES (p_inserted_id, p_nickname, p_birthdate, v_country, IF(p_is_active = 1, b'1', b'0'));
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
